#!/usr/bin/env python3
"""Two source-bounded allegation/adjudication networks; no inferred guilt or money receipts."""
import json, pathlib
ROOT=pathlib.Path(__file__).resolve().parent
OUT=ROOT.parent/'policy.json'
D={'sources':[],'entities':[],'relationships':[],'records':[],'localities':[]}
ROUTE='/allegations'
P=['finance','capital','debt-relief','justice']
T=['transport','public-works','public-funds','justice']

def src(i,title,url,publisher,date,loc,summary,limits=(),tier='documented'):
 D['sources'].append(dict(id=i,title=title,url=url,publisher=publisher,publishedAt=date,retrievedAt='2026-10-07',locator=loc,summary=summary,tier=tier,limitations=list(limits)))
def geo(s,states=None,note=None):
 return [dict(scope='state' if states and len(states)==1 else 'multi-state' if states else 'national',stateCodes=states or [],localityIds=[],basis='project-location' if states else 'national-context',note=note or ('Explicit project or auction jurisdiction; no coordinates inferred.' if states else 'India institutional or investor-scheme context; not evidence of a payment in every state.'),sourceIds=s)]
def dims(s,dom,states=None,layers=None,limits=()):
 return dict(sourceIds=s,domains=dom,layers=layers or ['organisations','funding','legal'],route=ROUTE,geography=geo(s,states),limitations=list(limits))
def ent(i,label,typ,summary,s,dom,states=None,resolved=True,limits=()):
 D['entities'].append(dict(id=i,label=label,type=typ,resolved=resolved,identityBasis='Exact named entity or expressly labelled source-defined cohort/instrument; no name-only corporate crosswalk.',summary=summary,**dims(s,dom,states,limits=limits)))
def amt(v,u,stage,period):return dict(value=v,currency='INR',unit=u,stage=stage,period=period)
def rel(i,a,b,label,summary,s,dom,date,records,responses=(),amounts=(),tier='documented',kind='documented-relationship',status=None,asof=None,end=None,states=None,limits=(),alts=(),falsifier=None):
 D['relationships'].append(dict(id=i,**{'from':a,'to':b},kind=kind,label=label,tier=tier,status=status or 'Dated source-supported relationship; see financial stage and response',statusAsOf=asof or date,fromDate=date,toDate=end or date,dateBasis='Date of the specified instrument, finding or observation, not an inferred transaction or continuing status.',summary=summary,alternativeExplanations=list(alts),falsifier=falsifier or 'A corrected original instrument, transaction reconciliation or later reasoned order changing this specific assertion would require revision.',responseIds=list(responses),recordIds=list(records),amounts=list(amounts),**dims(s,dom,states,limits=limits)))
def rec(i,title,summary,s,dom,date,ents,rels,period,response,kind='evidence-record',tier='documented',status=None,asof=None,end=None,amounts=(),states=None,limits=(),alts=(),falsifier=None):
 D['records'].append(dict(id=i,title=title,summary=summary,kind=kind,tier=tier,status=status or 'Dated finding or response; current limits stated',statusAsOf=asof or date,fromDate=date,toDate=end or date,dateBasis='Event dates and last verified status are distinct; historical aggregates are expressly labelled in the amount period.',entityIds=ents,relationshipIds=rels,period=period,response=response,alternativeExplanations=list(alts),falsifier=falsifier or 'Check the cited original against any subsequent order and trace receipts separately from assessed amounts or asset values.',amounts=list(amounts),**dims(s,dom,states,layers=['organisations','funding','legal','review'],limits=limits)))

